//! The province-graph GNN forward pass in pure Rust; weight
//! documents parse through serde_json.
//!
//! [`general_gnn::GeneralGnn`] is the pure forward pass: weights in as
//! JSON (serde_json-parsed and fully validated, refusing malformed input), province-plane
//! rows and directed edges in, candidate scores out. The parity
//! fixtures under `tests/data/` were generated by the real
//! torch/torch_geometric reference (`fixtures/gen_parity.py`, which
//! also exports trained checkpoints) — regenerating them needs only
//! that existing environment, no training run.

pub mod general_gnn;

pub use general_gnn::{GeneralGnn, HEADS, NODE, RULES};
